import networkx as nx
import random

def find_graph():
    while True:
        num_edges = random.randint(10, 14)
        G = nx.gnm_random_graph(8, num_edges)

        degrees = [d for n, d in G.degree()]
        if min(degrees) >= 2 and max(degrees) <= 4:
            # Check chromatic number
            # A graph has chromatic number <= 3 if it can be colored with 3 colors
            # It has chromatic number >= 3 if it cannot be colored with 2 colors (i.e., not bipartite)
            if not nx.is_bipartite(G):
                # Check if it can be colored with 3 colors
                coloring = nx.coloring.greedy_color(G, strategy='largest_first')
                # greedy_color doesn't guarantee optimal, but we can check if max color <= 2 (0, 1, 2)
                # Actually, let's use a proper chromatic number function or just check all 3-colorings
                # networkx has a function for chromatic number? No, but we can use greedy and if it uses 3, we are good.
                # Wait, greedy might use 4 even if 3 is possible.
                # Let's just use a simple backtracking for 3-coloring.

                def is_3_colorable(G):
                    colors = {}
                    def color_node(node):
                        if node == 8:
                            return True
                        for c in range(3):
                            if all(colors.get(neighbor) != c for neighbor in G.neighbors(node)):
                                colors[node] = c
                                if color_node(node + 1):
                                    return True
                                del colors[node]
                        return False
                    return color_node(0)

                if is_3_colorable(G):
                    return list(G.edges())

edges = find_graph()
